Đã sửa trực tiếp luồng lưu `SIM_TrainingLevel_SpecialBranch` trong:

`1.WEB -CTT/Controls/Declaration/SpecialBranchEdit.ascx.cs`

Thay đổi chính:
- Không còn gọi `SIM_TrainingLevel_SpecialBranch.Add()/Delete()` từ `SimsObject.dll`.
- Dùng trực tiếp `DCore.IData` của transaction hiện tại để gọi:
  - `SIM_TrainingLevel_SpecialBranch_ADD`
  - `SIM_TrainingLevel_SpecialBranch_DELETE`
- Nếu lỗi, transaction được rollback và hiển thị lỗi SQL cụ thể thay vì thông báo chung.

```223:261:1.WEB -CTT/Controls/Declaration/SpecialBranchEdit.ascx.cs
public bool SaveTrainingLevel(DCore.IData objIDB)
{
    HiddenField hidID = null, hidTrainingLevelID;
    try
    {
        for (int i = 0; i < gvTrainingLevel.Rows.Count; i++)
        {
            // ...
            if (chk.Checked && hidID.Value == "")
            {
                objIDB.CreateNewStoredProcedure("SIM_TrainingLevel_SpecialBranch_ADD");
                objIDB.AddParameter("@TrainingLevelID", hidTrainingLevelID.Value);
                objIDB.AddParameter("@SpecialBranchID", this.SpecialBranchID);
                objIDB.AddParameter("@CreatedUser", User.UserName);
                objIDB.ExecNonQuery();
            }
            else if (!chk.Checked && hidID.Value != "")
            {
                objIDB.CreateNewStoredProcedure("SIM_TrainingLevel_SpecialBranch_DELETE");
                objIDB.AddParameter("@TrainingLevel_SpecialBranchID", Convert.ToInt32(hidID.Value));
                objIDB.ExecNonQuery();
            }
        }
        return true;
    }
    catch (Exception objEx)
    {
        objSpecialBranch.RollBackTransaction();
        MsgBox.ShowError("Việc cập nhật hệ đào tạo bị lỗi: " + objEx.Message);
        return false;
    }
}
```

